referenceSolutions.javascript:
function selectionProofBossReceipt(readings, k) {
  const a=readings; let out=[];
  const sums=new Set();function visit(i,s){if(i===a.length){sums.add(s);return;}visit(i+1,s);visit(i+1,s+a[i]);}visit(0,0);out=[...sums].sort((x,y)=>x-y);
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}

